(()=>{
'use strict';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const $=s=>document.querySelector(s),D=NoirEpisodes;let detailShow=null,playerShow=null,active=null,detailSeason=null,drawerSeason=null,spoilers=false,detailError=false,playerError=false;
try{spoilers=localStorage.getItem('noir:spoilerShield')==='true'}catch{}
const dateText=d=>{if(!d)return '';const date=new Date(d+'T12:00:00Z');return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(date)};
function optionList(list,selected){return list.map(s=>`<option value="${s}" ${s===selected?'selected':''}>Season ${s}</option>`).join('')}
function episodeCard(m,e,inPlayer){const isActive=playerShow?.id===m.id&&active?.season===e.season&&active?.episode===e.episode;const locked=!D.available(e),concealed=spoilers&&!isActive;const src=e.image||m.background||m.poster;const safe=typeof src==='string'&&src.startsWith('https://')?src:'';const meta=[e.runtime?e.runtime+' min':'',dateText(e.date)].filter(Boolean).join(' · ');return `<button class="episode-card ${isActive?'is-current':''} ${concealed?'spoiler-covered':''}" data-episode-show="${esc(m.id)}" data-episode-season="${e.season}" data-episode-number="${e.episode}" ${locked?'disabled':''} aria-label="${locked?'Not yet released: ':'Play '}${esc(m.name)}, season ${e.season}, episode ${e.episode}: ${esc(e.name)}" ${isActive?'aria-current="true"':''}><span class="episode-art"><img src="${esc(safe)}" alt="" loading="lazy" onerror="this.style.opacity='0'"><span class="episode-play">${locked?'◷':isActive?'✓':'▶'}</span></span><span class="episode-copy"><strong>${e.episode}. ${esc(e.name)}</strong>${meta?`<small>${esc(meta)}</small>`:''}<span class="episode-description">${concealed?'Synopsis hidden by Spoiler Shield.':esc(e.description||'No episode synopsis available.')}</span>${isActive?'<span class="episode-current">NOW SELECTED</span>':locked?'<span class="episode-current">COMING SOON</span>':''}</span>${inPlayer&&isActive?'<span class="episode-tick">✓</span>':''}</button>`}
function renderDetail(){const target=$('#titleEpisodes');if(!target||!detailShow||target.dataset.show!==detailShow.id)return;const state=D.get(detailShow.id);if(!state){target.innerHTML=`<div class="episode-section-heading"><div><h2>Episodes</h2><p>${detailError?'Episode information couldn’t load.':'Loading episode information…'}</p></div>${detailError?'<button class="liquid-control" data-episode-retry="detail">Try again</button>':''}</div><div class="episode-skeletons" aria-hidden="true"><span></span><span></span><span></span></div>`;return}
 const ss=D.seasons(state.episodes);if(!ss.includes(detailSeason))detailSeason=ss.includes(active?.season)?active.season:ss[0];const rows=state.episodes.filter(e=>e.season===detailSeason);target.innerHTML=`<div class="episode-section-heading"><div><div class="episode-heading-line"><h2>Episodes</h2><button class="spoiler-toggle liquid-control" data-spoiler-toggle aria-pressed="${spoilers}">◇ Spoiler shield ${spoilers?'on':'off'}</button></div><p>${rows.length?`${rows.length} episodes · scroll to explore`:'No episode information is available for this title.'}</p></div>${ss.length?`<label class="season-picker"><span class="sr-only">Season for title episodes</span><select data-season-picker="detail" aria-label="Season for title episodes">${optionList(ss,detailSeason)}</select><span>⌄</span></label>`:''}</div><div class="episode-grid">${rows.map(e=>episodeCard(detailShow,e,false)).join('')}</div>${state.attribution?`<a class="episode-attribution" href="${esc(state.attribution)}" target="_blank" rel="noopener noreferrer">Episode information: TVmaze ↗</a>`:''}`}
function renderDrawer(){const target=$('#episodeDrawerContent');if(!target||!playerShow)return;const state=D.get(playerShow.id);if(!state){target.innerHTML=`<p class="episode-empty">${playerError?'Episode information couldn’t load.':'Loading episodes…'}</p>${playerError?'<button class="liquid-control" data-episode-retry="player">Try again</button>':''}`;return}const ss=D.seasons(state.episodes);if(!ss.includes(drawerSeason))drawerSeason=ss.includes(active?.season)?active.season:ss[0];const rows=state.episodes.filter(e=>e.season===drawerSeason);target.innerHTML=`<div class="episode-drawer-season"><label>Season <span class="season-picker"><select data-season-picker="player" aria-label="Season in player">${optionList(ss,drawerSeason)}</select><span>⌄</span></span></label><span>${rows.length} episodes</span></div><div class="episode-drawer-list">${rows.map(e=>episodeCard(playerShow,e,true)).join('')||'<p class="episode-empty">No episodes available.</p>'}</div>${state.attribution?`<a class="episode-attribution" href="${esc(state.attribution)}" target="_blank" rel="noopener noreferrer">Episode information: TVmaze ↗</a>`:''}`}
function updateNow(){const ep=D.get(playerShow?.id)?.episodes.find(e=>e.season===active?.season&&e.episode===active?.episode);$('#playingEpisode').textContent=playerShow?`S${active?.season||1} · E${active?.episode||1}${ep?' — '+ep.name:''}`:'';const prev=D.adjacent(D.get(playerShow?.id)?.episodes||[],active?.season,active?.episode,-1),next=D.adjacent(D.get(playerShow?.id)?.episodes||[],active?.season,active?.episode,1);$('#previousEpisode').disabled=!prev;$('#nextEpisode').disabled=!next;$('#episodeToggle').hidden=!playerShow;$('#episodeNavigation').hidden=!playerShow;const loading=$('#loadingEpisode');if(loading&&playerShow)loading.textContent=$('#playingEpisode').textContent;}
async function loadDetail(m){detailError=false;renderDetail();try{await D.load(m)}catch{detailError=true}if(detailShow?.id===m.id)renderDetail()}
async function mountDetail(m){detailShow=m;const target=$('#titleEpisodes');if(!target)return;target.dataset.show=m.id;await loadDetail(m)}
async function setPlayer(m,season,episode){playerShow=m.type==='tv'?m:null;active=playerShow?{season:Number(season),episode:Number(episode)}:null;drawerSeason=active?.season||null;playerError=false;closeDrawer(false);updateNow();if(!playerShow)return;try{await D.load(m)}catch{playerError=true}if(playerShow?.id===m.id){renderDrawer();updateNow()}}
function openDrawer() {if(!playerShow)return;drawerSeason=active?.season;renderDrawer();$('#episodePanel').hidden=false;$('#episodeToggle').setAttribute('aria-expanded','true');$('#episodeDrawer').querySelector('select')?.focus();}
function closeDrawer(restore=true){$('#episodePanel').hidden=true;$('#episodeToggle').setAttribute('aria-expanded','false');if(restore&&!$('#episodeToggle').hidden)$('#episodeToggle').focus()}
function select(m,e){if(!m||!e||!D.available(e))return;active={season:e.season,episode:e.episode};closeDrawer(false);document.dispatchEvent(new CustomEvent('noir:episode-selected',{detail:{show:m,episode:e}}))}
function revealDetail(m){detailShow=m;$('#titleEpisodes')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('#titleEpisodes select')?.focus({preventScroll:true})}
$('#episodeToggle').onclick=()=>$('#episodePanel').hidden?openDrawer():closeDrawer();$('#closeEpisodes').onclick=()=>closeDrawer();$('#episodeScrim').onclick=()=>closeDrawer();
for(const [selector,dir]of [['#previousEpisode',-1],['#nextEpisode',1]])$(selector).onclick=()=>{const ep=D.adjacent(D.get(playerShow?.id)?.episodes||[],active?.season,active?.episode,dir);if(ep)select(playerShow,ep)};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.episodeShow){const m=playerShow?.id===b.dataset.episodeShow?playerShow:detailShow;if(m?.id!==b.dataset.episodeShow)return;const ep=D.get(m.id)?.episodes.find(x=>x.season===Number(b.dataset.episodeSeason)&&x.episode===Number(b.dataset.episodeNumber));select(m,ep)}if(b.hasAttribute('data-spoiler-toggle')){spoilers=!spoilers;try{localStorage.setItem('noir:spoilerShield',spoilers)}catch{}renderDetail();renderDrawer()}if(b.dataset.episodeRetry){if(b.dataset.episodeRetry==='detail'&&detailShow)loadDetail(detailShow);if(b.dataset.episodeRetry==='player'&&playerShow)setPlayer(playerShow,active.season,active.episode)}});
document.addEventListener('change',e=>{if(e.target.dataset.seasonPicker==='detail'){detailSeason=Number(e.target.value);renderDetail()}if(e.target.dataset.seasonPicker==='player'){drawerSeason=Number(e.target.value);renderDrawer()}});
document.addEventListener('noir:episodes-updated',e=>{if(detailShow?.id===e.detail.id)renderDetail();if(playerShow?.id===e.detail.id){renderDrawer();updateNow()}});
document.addEventListener('keydown',e=>{if($('#episodePanel').hidden)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeDrawer()}if(e.key==='Tab'){const items=[...$('#episodeDrawer').querySelectorAll('button:not(:disabled),select,a[href]')].filter(x=>x.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}},true);
window.NoirEpisodeUI={mountDetail,setPlayer,revealDetail,close:closeDrawer,current:()=>active};
})();
